<?php
use AISkillsHub\Core\Developers\Frontend as Developers;
use AISkillsHub\Core\Contributions\Ui;
use AISkillsHub\Core\Accounts\Frontend as Accounts;
use AISkillsHub\Core\Frontend\View;
defined( 'ABSPATH' ) || exit;
$c = Developers::context(); $locale = $c['locale']; $route = $c['route']; $params = $c['params'];
$t = static fn( string $key ): string => Developers::t( $key, $locale );
$url = static fn( string $target, array $query = array() ): string => Developers::url( $target, $locale, $query );
$developer = $c['developer'] ?? array(); $draft = $developer['draft'] ?? array();
$value = static fn( string $key, string $fallback = '' ): string => (string) ( $c['values'][ $key ] ?? $draft[ $key ] ?? $fallback );
$form = static function ( string $action, bool $dirty = false ) use ( $route, $params, $url ): void { echo '<form method="post" action="' . esc_url( $url( $route, $params ) ) . '" class="account-form contributions-form" data-contribution-form' . ( $dirty ? ' data-contribution-draft' : '' ) . '>' . Developers::fields( $action ) . '<div class="account-honeypot" aria-hidden="true"><label>Company<input type="text" name="company" tabindex="-1" autocomplete="off"></label></div>'; };
$button = static function ( string $key ) use ( $t ): void { echo '<button type="submit" class="account-button account-button-primary" data-pending-label="' . esc_attr( $t( 'working' ) ) . '">' . esc_html( $t( $key ) ) . '</button>'; };
?>
<?php if ( 'developer' === $route && isset( $c['developer'] ) && ! in_array( $c['status'], array( 403, 404, 405 ), true ) ) : ?>
<section class="account-panel account-section"><div class="contributions-record-heading"><h2><?php echo esc_html( $t( 'profile_state' ) ); ?></h2><span class="account-badge"><?php echo esc_html( $t( 'state.' . ( $developer['state'] ?: 'none' ) ) ); ?></span></div><p class="contributions-copy"><?php echo esc_html( $developer['feedback'] ?: $t( 'no_feedback' ) ); ?></p><?php if ( ! empty( $developer['opt_in'] ) && ! empty( $developer['approved']['handle'] ) ) : ?><div class="account-inline-actions"><?php foreach ( array( 'zh_CN' => '中文', 'en_US' => 'English' ) as $language => $label ) : if ( empty( $developer['approved']['translations'][ $language ]['display_name'] ) || empty( $developer['approved']['translations'][ $language ]['bio'] ) ) { continue; } ?><a class="account-text-action" href="<?php echo esc_url( Developers::url( 'public', $language, array( 'handle' => $developer['approved']['handle'] ) ) ); ?>"><?php echo esc_html( $t( 'view_public' ) . ' · ' . $label ); ?></a><?php endforeach; ?></div><?php endif; ?></section>
<section class="account-panel account-section"><h2><?php echo esc_html( $t( 'developer' ) ); ?></h2><p><?php echo esc_html( $t( 'profile_help' ) ); ?></p>
<?php $form( 'profile', true ); ?><input type="hidden" name="revision" value="<?php echo esc_attr( (string) ( $c['values']['revision'] ?? $developer['revision'] ) ); ?>">
<?php Ui::field( 'handle', $t( 'handle' ), $value( 'handle' ), 50, 0, $t( 'handle_help' ), true ); Ui::field( 'github_url', $t( 'github_url' ), $value( 'github_url' ), 1000 ); Ui::field( 'website_url', $t( 'website_url' ), $value( 'website_url' ), 1000 ); ?>
<p class="account-help"><?php echo esc_html( $t( 'translations_help' ) ); ?></p>
<?php foreach ( array( 'zh_CN' => '简体中文', 'en_US' => 'English' ) as $language => $label ) : ?>
<fieldset class="contributions-language"><legend><?php echo esc_html( $label ); ?></legend>
<?php foreach ( array( 'display_name' => array( 100, 0 ), 'bio' => array( 2000, 6 ), 'seo_title' => array( 191, 0 ), 'seo_description' => array( 320, 3 ) ) as $key => $settings ) { Ui::field( $language . '_' . $key, $t( $key ), (string) ( $c['values'][ $language . '_' . $key ] ?? $draft['translations'][ $language ][ $key ] ?? '' ), $settings[0], $settings[1] ); } ?>
</fieldset><?php endforeach; ?>
<?php foreach ( array( 'opt_in', 'public_avatar', 'show_contributions' ) as $key ) : $checked = array_key_exists( $key, $c['values'] ) ? '1' === $c['values'][ $key ] : ! empty( $draft[ $key ] ?? ( 'opt_in' === $key ? $developer['opt_in'] : false ) ); ?><label class="account-check"><input type="checkbox" name="<?php echo esc_attr( $key ); ?>" value="1" <?php checked( $checked ); ?> <?php echo 'opt_in' === $key ? 'required' : ''; ?>><span><?php echo esc_html( $t( $key ) ); ?></span></label><?php endforeach; ?>
<p class="account-help"><?php echo esc_html( $t( 'avatar_help' ) ); ?> <a class="account-text-action" href="<?php echo esc_url( Accounts::url( 'profile', $locale ) ); ?>"><?php echo esc_html( \AISkillsHub\Core\Accounts\Strings::get( 'profile', $locale ) ); ?></a></p>
<?php $button( 'submit_profile' ); ?></form></section>
<?php if ( ! empty( $developer['opt_in'] ) ) : ?><section class="account-panel account-section"><h2><?php echo esc_html( $t( 'withdraw_profile' ) ); ?></h2><?php $form( 'profile_withdraw' ); ?><input type="hidden" name="revision" value="<?php echo esc_attr( (string) ( $c['values']['revision'] ?? $developer['revision'] ) ); ?>"><label class="account-check"><input type="checkbox" name="confirm" value="1" required><span><?php echo esc_html( $t( 'confirm_profile' ) ); ?></span></label><?php $button( 'withdraw_profile' ); ?></form></section><?php endif; ?>
<?php if ( isset( $c['claims'] ) ) : $listing = $c['claims']; ?><section class="account-panel account-section"><h2><?php echo esc_html( $t( 'my_claims' ) ); ?></h2><form method="get" action="<?php echo esc_url( $url( 'developer' ) ); ?>" class="contributions-filters"><div class="account-field"><label for="claim-state"><?php echo esc_html( $t( 'state' ) ); ?></label><select name="state" id="claim-state"><?php foreach ( array( 'all', 'pending', 'approved', 'rejected', 'withdrawn', 'revoked', 'disputed' ) as $state ) : ?><option value="<?php echo esc_attr( $state ); ?>" <?php selected( $params['state'] ?? 'all', $state ); ?>><?php echo esc_html( $t( 'all' === $state ? 'all' : 'state.' . $state ) ); ?></option><?php endforeach; ?></select></div><button type="submit" class="account-button account-button-secondary"><?php echo esc_html( $t( 'apply' ) ); ?></button><a class="account-text-action" href="<?php echo esc_url( $url( 'developer' ) ); ?>"><?php echo esc_html( $t( 'clear_filters' ) ); ?></a></form>
<?php if ( ! $listing['items'] ) : ?><p><?php echo esc_html( $t( 'empty_claims' ) ); ?></p><?php endif; ?><div class="contributions-records"><?php foreach ( $listing['items'] as $claim ) : ?><article class="contributions-record contributions-record-bordered"><div class="contributions-record-heading"><h3><?php echo esc_html( $claim['skill']['title'] ?? $t( 'unavailable_skill' ) ); ?></h3><span class="account-badge"><?php echo esc_html( $t( 'state.' . $claim['state'] ) ); ?></span></div><p class="account-help"><?php echo esc_html( '#' . $claim['id'] . ' · ' . $t( 'role.' . $claim['claim_role'] ) . ' · ' . $claim['created_at'] . ' UTC' ); ?></p><a class="account-text-action" href="<?php echo esc_url( $url( 'claim', array( 'id' => $claim['id'] ) ) ); ?>"><?php echo esc_html( $t( 'view_claim' ) ); ?></a></article><?php endforeach; ?></div><?php Ui::pagination( $listing, $url, $route, $params, $t ); ?></section><?php endif; ?>
<?php elseif ( 'claim' === $route && ( isset( $c['skill'] ) || isset( $c['claim'] ) ) && ! in_array( $c['status'], array( 403, 404, 405 ), true ) ) : ?>
<p><a class="account-text-action" href="<?php echo esc_url( $url( 'developer' ) ); ?>"><?php echo esc_html( $t( 'back' ) ); ?></a></p><div class="account-notice"><p><?php echo esc_html( $t( 'claim_help' ) ); ?></p></div>
<?php if ( isset( $c['claim'] ) ) : $claim = $c['claim']; ?>
<section class="account-panel account-section"><div class="contributions-record-heading"><h2><?php echo esc_html( $claim['skill']['title'] ?? $t( 'unavailable_skill' ) ); ?></h2><span class="account-badge"><?php echo esc_html( $t( 'state.' . $claim['state'] ) ); ?></span></div><dl class="contributions-readonly"><div><dt><?php echo esc_html( $t( 'claim_role' ) ); ?></dt><dd><?php echo esc_html( $t( 'role.' . $claim['claim_role'] ) ); ?></dd></div><div><dt><?php echo esc_html( $t( 'locale' ) ); ?></dt><dd><?php echo esc_html( 'zh_CN' === ( $claim['proof']['locale'] ?? '' ) ? '简体中文' : 'English' ); ?></dd></div><div><dt><?php echo esc_html( $t( 'proof_kind' ) ); ?></dt><dd><?php echo esc_html( $t( 'proof.' . $claim['proof_kind'] ) ); ?></dd></div><div><dt><?php echo esc_html( $t( 'source_revision' ) ); ?></dt><dd><?php echo esc_html( (string) $claim['source_revision'] ); ?></dd></div><div><dt><?php echo esc_html( $t( 'reason' ) ); ?></dt><dd class="contributions-copy"><?php echo esc_html( $claim['proof']['reason'] ?? '' ); ?></dd></div><div><dt><?php echo esc_html( $t( 'evidence_urls' ) ); ?></dt><dd class="contributions-copy"><?php echo esc_html( implode( "\n", $claim['proof']['evidence_urls'] ?? array() ) ); ?></dd></div></dl><h3><?php echo esc_html( $t( 'feedback' ) ); ?></h3><p class="contributions-copy"><?php echo esc_html( $claim['feedback'] ?: $t( 'no_feedback' ) ); ?></p></section>
<?php if ( in_array( $claim['state'], array( 'pending', 'approved', 'disputed' ), true ) ) : ?><section class="account-panel account-section"><h2><?php echo esc_html( $t( 'withdraw_claim' ) ); ?></h2><?php $form( 'claim_withdraw' ); ?><input type="hidden" name="expected_state" value="<?php echo esc_attr( $c['values']['expected_state'] ?? $claim['state'] ); ?>"><label class="account-check"><input type="checkbox" name="confirm" value="1" required><span><?php echo esc_html( $t( 'confirm_claim' ) ); ?></span></label><?php $button( 'withdraw_claim' ); ?></form></section><?php endif; ?>
<?php else : ?>
<section class="account-panel account-section"><h2><a class="account-text-action" href="<?php echo esc_url( View::skillUrl( $c['skill'], $locale ) ); ?>"><?php echo esc_html( $c['skill']['title'] ); ?></a></h2><p class="account-help"><?php echo esc_html( $t( 'evidence_help' ) ); ?></p>
<?php $form( 'claim', true ); ?><input type="hidden" name="source_revision" value="<?php echo esc_attr( $value( 'source_revision', (string) $c['source_revision'] ) ); ?>">
<div class="account-field"><label for="claim-role"><?php echo esc_html( $t( 'claim_role' ) ); ?></label><select name="claim_role" id="claim-role"><?php foreach ( array( 'author', 'maintainer' ) as $role ) : ?><option value="<?php echo esc_attr( $role ); ?>" <?php selected( $value( 'claim_role', 'author' ), $role ); ?>><?php echo esc_html( $t( 'role.' . $role ) ); ?></option><?php endforeach; ?></select></div>
<div class="account-field"><label for="claim-proof"><?php echo esc_html( $t( 'proof_kind' ) ); ?></label><select name="proof_kind" id="claim-proof"><?php foreach ( array( 'authored_source', 'license_credit', 'repository_control', 'other' ) as $proof ) : ?><option value="<?php echo esc_attr( $proof ); ?>" <?php selected( $value( 'proof_kind', 'authored_source' ), $proof ); ?>><?php echo esc_html( $t( 'proof.' . $proof ) ); ?></option><?php endforeach; ?></select></div>
<div class="account-field"><label for="claim-locale"><?php echo esc_html( $t( 'locale' ) ); ?></label><select id="claim-locale" name="locale"><?php foreach ( array( 'zh_CN' => '简体中文', 'en_US' => 'English' ) as $language => $label ) : ?><option value="<?php echo esc_attr( $language ); ?>" <?php selected( $value( 'locale', $locale ), $language ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></div>
<?php Ui::field( 'reason', $t( 'reason' ), $value( 'reason' ), 4000, 7, '', true ); Ui::field( 'evidence_urls', $t( 'evidence_urls' ), $value( 'evidence_urls' ), 12000, 5, $t( 'evidence_help' ), true ); $button( 'submit_claim' ); ?></form></section>
<?php endif; ?>
<?php endif; ?>
